**Game Prototype: Treasure Hunter**

The game is a simple text-based adventure game where the player's goal is to find the hidden treasure by navigating through a series of rooms.

**Game Code:**

```python
# treasure_hunter.py

# Import the necessary modules
import random

# Define a class for the game
class Room:
    def __init__(self, name, description, items=None, exits=None):
        self.name = name
        self.description = description
        self.items = items if items else []
        self.exits = exits if exits else {}

    def add_exit(self, direction, room):
        self.exits[direction] = room

class Player:
    def __init__(self):
        self.inventory = []

    def add_item(self, item):
        self.inventory.append(item)

class Game:
    def __init__(self):
        self.rooms = {
            'kitchen': Room('Kitchen', 'You are in a dark kitchen.'),
            'garden': Room('Garden', 'You are in a beautiful garden.', items=['key']),
            'treasure_room': Room('Treasure Room', 'You have found the treasure!', items=['treasure'])
        }
        self.current_room = self.rooms['kitchen

